namespace sv_9045e0e65dd94b55b4401c4f80ee0322.Services;

/// <summary>
/// Scoped service that tracks the currently selected warehouse for a single user circuit.
/// Components subscribe to <see cref="OnChange"/> to react when the selection changes.
/// </summary>
public class WarehouseState
{
    public static readonly IReadOnlyList<(string Id, string Name)> AvailableWarehouses =
    [
        ("WH-A", "Warehouse A"),
        ("WH-B", "Warehouse B"),
        ("WH-C", "Warehouse C"),
    ];

    public string SelectedWarehouseId { get; private set; } = AvailableWarehouses[0].Id;

    public string SelectedWarehouseName =>
        AvailableWarehouses.First(w => w.Id == SelectedWarehouseId).Name;

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (warehouseId == SelectedWarehouseId)
            return;

        SelectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

namespace sv_9045e0e65dd94b55b4401c4f80ee0322.Services;

/// <summary>
/// Scoped service that polls for low-stock alerts and notifies all subscribers.
/// Polling is controlled by <see cref="StartPolling"/> / <see cref="StopPolling"/>
/// so it only runs while the dashboard is visible.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _activePollers;

    public int CurrentAlertCount { get; private set; }

    /// <summary>
    /// Fired from a background thread — subscribers must use InvokeAsync(StateHasChanged).
    /// </summary>
    public event Action? OnAlertCountChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
    }

    /// <summary>Simulates a database query returning a random low-stock count.</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Begins polling every 10 seconds. Ref-counted so multiple callers are safe,
    /// but in practice only the Dashboard calls this.
    /// </summary>
    public void StartPolling()
    {
        _activePollers++;
        if (_activePollers > 1)
            return;

        _cts = new CancellationTokenSource();
        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        _ = PollLoopAsync(_cts.Token);
    }

    /// <summary>Stops polling when the last subscriber leaves.</summary>
    public void StopPolling()
    {
        _activePollers = Math.Max(0, _activePollers - 1);
        if (_activePollers > 0)
            return;

        CancelPolling();
    }

    /// <summary>Fetch once immediately (used on init and warehouse change).</summary>
    public async Task RefreshAsync()
    {
        var count = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        CurrentAlertCount = count;
        OnAlertCountChanged?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fire once immediately so the UI has data right away.
        await RefreshAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (!await _timer!.WaitForNextTickAsync(ct))
                    break;

                await RefreshAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private void CancelPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        CancelPolling();
    }
}

