@rendermode InteractiveServer
@inject WarehouseState WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

@using sv_9045e0e65dd94b55b4401c4f80ee0322.Services

<select class="form-select form-select-sm" style="width: auto;"
        value="@WarehouseState.SelectedWarehouseId"
        @onchange="OnWarehouseChanged">
    @foreach (var (id, name) in WarehouseState.AvailableWarehouses)
    {
        <option value="@id">@name</option>
    }
</select>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleWarehouseChanged;
    }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
            // Refresh alerts immediately for the new warehouse.
            await AlertService.RefreshAsync();
        }
    }

    private void HandleWarehouseChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleWarehouseChanged;
    }
}

@rendermode InteractiveServer
@inject InventoryAlertService AlertService
@implements IDisposable

@using sv_9045e0e65dd94b55b4401c4f80ee0322.Services

@if (AlertService.CurrentAlertCount > 0)
{
    <span class="badge bg-danger rounded-pill ms-2">@AlertService.CurrentAlertCount</span>
}
else
{
    <span class="badge bg-success rounded-pill ms-2">0</span>
}

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        // Timer fires from a background thread, so wrap in InvokeAsync.
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertCountChanged += _handler;
    }

    public void Dispose()
    {
        if (_handler is not null)
            AlertService.OnAlertCountChanged -= _handler;
    }
}

