    <div class="col-md-4">
        <div class="card @(_alertCount > 0 ? "border-danger" : "border-success")">
            <div class="card-body text-center">
                <h5 class="card-title">Low-Stock Alerts</h5>
                <span class="display-4 @(_alertCount > 0 ? "text-danger" : "text-success")">
                    @_alertCount
                </span>
                <p class="card-text mt-2">
                    items below minimum levels
                </p>
                <small class="text-muted">Refreshes every 10 seconds</small>
            </div>
